var EXTRA=[{dot:"gray",j:"EFORT Open Reviews",h:"Protesi monocompartimentale e totale nello stesso paziente: revisione sistematica nella gonartrosi bilaterale",v:"L'abstract non è disponibile su PubMed: il contenuto non è stato letto e va verificato aprendo l'articolo; D'Ambrosi, tuo riferimento sul quadricipite, è fra gli autori.",pmid:"42825407",doi:"10.1530/EOR-2025-0193",temi:["protesi monocompartimentale","protesi totale","gonartrosi bilaterale"]},{dot:"gray",j:"Sports Medicine - Open",h:"Calciatrici dopo il LCA: paura e scarsa fiducia frenano il rientro",v:"Scoping review di studi qualitativi e osservazionali: incertezza, paura, poca fiducia e scarso sostegno sociale come barriere, motivazione e identità atletica come facilitatori; pochi studi inclusi, nessuna misura di effetto.",pmid:"42828697",doi:"10.1186/s40798-026-01118-6",temi:["LCA","ritorno allo sport","fattori psicosociali"]},{dot:"gray",j:"Case Reports in Orthopedics",h:"Rottura bilaminare del tendine rotuleo con multilegamentosa, riparata con peroneo lungo",v:"Caso singolo in una donna adulta: riparazione primaria aumentata con innesto di peroneo lungo, buon esito a sei mesi; un caso non permette alcuna conclusione generale.",pmid:"42824672",doi:"10.1155/cro/5640221",temi:["tendine rotuleo","multilegamentosa","peroneo lungo"]},{dot:"gray",j:"Cureus",h:"Rottura del tendine rotuleo in età pediatrica: la revisione sistematica trova pochissimi casi",v:"Quasi tutti maschi, spesso con frattura della tuberosità tibiale e rotula alta; la dichiarata selezione degli studi sulle fratture della tuberosità distorce la frequenza associata.",pmid:"42824921",doi:"10.7759/cureus.115603",temi:["tendine rotuleo","pediatria","rotula alta"]},{dot:"gray",j:"The Knee",h:"Osteotomia derotativa sovramalleolare in età pediatrica con instabilità rotulea e torsione",v:"Serie osservazionale prospettica su dieci anni: punteggi funzionali migliorati a medio termine, con o senza stabilizzazione della rotula; nessun gruppo di controllo, quindi nessun confronto con la sola ricostruzione del MPFL.",pmid:"42815203",doi:"10.1016/j.knee.2026.104644",temi:["instabilità rotulea","torsione tibiale","adolescenti"]},{dot:"gray",j:"Sensors",h:"Dopo il LCA, il deficit di forza eccentrica nello squat flywheel resta nell'arto operato",v:"Studio trasversale su atleti di squadra: la forza è inferiore solo nella fase eccentrica dell'arto ricostruito; campione molto piccolo e differenze elettromiografiche non significative.",pmid:"42817281",doi:"10.3390/s26185745",temi:["LCA","forza eccentrica","asimmetrie"]},{dot:"gray",j:"Clinical Biomechanics",h:"Elastografia a onde di taglio dopo il LCA: il vasto mediale resta più morbido",v:"Revisione sistematica con pochi studi di qualità da scarsa a buona: la rigidità ridotta si associa a forza del quadricipite e a funzione; nessuno studio ha campionato la parte distale del vasto mediale obliquo.",pmid:"42815174",doi:"10.1016/j.clinbiomech.2026.106982",temi:["LCA","quadricipite","elastografia"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"Conversione da UKA a protesi totale: serve sempre un componente tibiale di revisione",v:"Serie retrospettiva piccola di un solo chirurgo, con abbinamento a protesi primarie e di revisione: esiti più scarsi rispetto alla primaria, simili alla revisione; follow-up medio di pochi anni.",pmid:"42824250",doi:"10.1007/s43465-026-01831-0",temi:["UKA","conversione","protesi totale"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"Protesi totale a perno mediale: miglioramenti a un anno in una serie prospettica",v:"Serie monocentrica senza gruppo di controllo e con un solo chirurgo: i punteggi migliorano rispetto al basale, ma non c'è un confronto con altri disegni di protesi.",pmid:"42824236",doi:"10.1007/s43465-026-01832-z",temi:["protesi totale","cinematica","perno mediale"]},{dot:"gray",j:"Cureus",h:"Cuneo di beta-fosfato tricalcico nell'osteotomia tibiale d'apertura: l'orientamento dei pori conta",v:"Prova biomeccanica in vitro, nessun paziente: l'orientamento dei pori cambia la resistenza alla compressione, e in uno dei due formati il cuneo commerciale resiste di più a spostamenti maggiori.",pmid:"42819325",doi:"10.7759/cureus.115507",temi:["osteotomia tibiale alta","biomateriali","biomeccanica"]},{dot:"gray",j:"The Journal of Orthopaedic & Sports Physical Therapy",h:"Dinamometri portatili per la forza di ginocchio e caviglia: affidabilità sufficiente nella maggior parte dei casi",v:"Revisione sistematica con meta-analisi e mappa delle lacune: l'affidabilità è sufficiente con certezza da moderata ad alta, la validità di criterio è poco studiata; utile per i criteri di rientro, non per l'esito.",pmid:"42823646",doi:"10.2519/jospt.2026.14091",temi:["forza muscolare","misure","ritorno allo sport"]}];

var SCOPERTE=[{t:"Un questionario cinese dedicato alla protesi totale: i pazienti orientali misurati con strumenti pensati per loro",v:"Un gruppo di Xi'an ha raffinato e validato su 1.748 pazienti in tre ospedali un questionario di esiti riferiti dal paziente costruito su interviste a pazienti cinesi: correlazione con il WOMAC r=0,698 (IC 95% 0,663-0,730). Vale la deviazione perché mostra come si misura la protesi in una cultura che non è la tua (buco orientale dichiarato); è uno strumento di misura, non uno studio clinico.",pmid:"42824605",doi:"10.1016/j.lanwpc.2026.101989",temi:["protesi totale","PROM","mondo orientale"]},{t:"Misurare automaticamente lo spessore della cartilagine in risonanza: funziona, ma solo dopo la calibrazione",v:"Frankfurt, 111 pazienti: il software automatico sovrastima lo spessore di 0,7 mm contro la misura manuale su densità protonica e di 0,9 mm su sequenza DESS; dopo una semplice calibrazione globale il bias scompare e l'accordo (ICC) raggiunge il livello dell'accordo fra le due sequenze (0,73). Vale la deviazione perché tocca l'imaging automatico della cartilagine, vicino ad AMIC e minced cartilage; la maggiore variabilità è proprio nelle sottoregioni rotulea e tibiale laterale.",pmid:"42823317",doi:"10.1016/j.acra.2026.09.025",temi:["cartilagine","risonanza magnetica","segmentazione automatica"]},{t:"Il calore perduto dell'articolazione: ipotesi dal Politecnico di Losanna",v:"Un articolo di prospettiva dell'EPFL propone che nelle fasi iniziali dell'artrosi la cartilagine dissipi la metà dell'energia della cartilagine sana e non si scaldi sotto carico: calore esterno più esercizio potrebbero restituire il segnale perduto. Vale la deviazione perché è bioingegneria svizzera su un'ipotesi nuova; è un'ipotesi con dati in vitro, non uno studio sull'uomo.",pmid:"42828279",doi:"10.1016/j.mbm.2026.100213",temi:["artrosi","bioingegneria","cartilagine"]}];

var SOC={"1": {"video": "Lo slope tibiale è l'inclinazione all'indietro della superficie su cui poggia il femore, nella parte interna del ginocchio. Uno studio pubblicato a ottobre 2026 dal gruppo di Berlino ha misurato lo slope in duecentottanta pazienti con danni alla cartilagine operati con un trapianto di cellule di cartilagine, e li ha confrontati con controlli accoppiati per età e sesso.\n\nLo slope medio è 9,73 gradi nei pazienti e 8,92 nei controlli: una differenza di 0,8 gradi, con un intervallo di incertezza da 0,32 a 1,27. La differenza compare per le lesioni dietro la rotula e nella troclea, la doccia in cui scorre la rotula, non per quelle dei condili.\n\nIl limite: è un'associazione osservata a posteriori. Lo studio non dice che lo slope causi il danno, né che correggerlo lo prevenga, e riguarda solo pazienti poi operati con questa tecnica. Gli autori stessi giudicano incerta la rilevanza clinica.", "linkedin": "Slope tibiale mediale e lesioni cartilaginee: uno studio caso-controllo di livello III (Journal of ISAKOS, ottobre 2026, Charité Berlino) su 280 pazienti con lesione cartilaginea trattati con MACI.\n\nMPTS 9,73° contro 8,92° nei controlli accoppiati: differenza aggiustata 0,80° (IC 95% 0,32-1,27). Per sede: retropatellare +0,92° (IC 95% 0,05-1,80), trocleare +1,60° (IC 95% 0,11-3,10), nessuna differenza per i condili. ICC fra lettori 0,921.\n\nLimite: studio retrospettivo, associazione e non causalità; differenza piccola, con intervalli vicini allo zero; popolazione selezionata. Gli autori giudicano incerta la rilevanza clinica.", "instagram": "Pendenza del piatto tibiale e cartilagine: una piccola associazione.\nSu 280 persone con danni alla cartilagine, la pendenza è in media 9,73 gradi contro 8,92 nei controlli.\n\nIl legame c'è per la zona dietro la rotula e per la troclea, non per i condili.\n\nLimite: è un'associazione, non una causa; la differenza è molto piccola.\nFonte: PubMed, PMID 42829203.", "pazienti": "Nel ginocchio, la superficie della tibia su cui poggia il femore non è piatta: è leggermente inclinata all'indietro. Questa inclinazione si chiama slope. Un gruppo di Berlino ha misurato lo slope in 280 persone con danni alla cartilagine del ginocchio, operate con un trapianto di cartilagine, e lo ha confrontato con quello di persone simili per età e sesso.\n\nIn media lo slope è di 9,73 gradi nelle persone con il danno e di 8,92 nelle altre: meno di un grado di differenza. Il legame è risultato presente per i danni dietro la rotula e nell'incavo in cui scorre la rotula, non per quelli delle altre zone.\n\nÈ un risultato da non sovrainterpretare: lo studio guarda indietro nel tempo, non dimostra che la pendenza causi il danno e non dice se correggerla possa prevenirlo. Gli stessi autori scrivono che il significato per i pazienti è ancora incerto. Se si hanno dubbi, conviene parlarne con il proprio ortopedico."}};

var SOCV={"1": {"video": {"chir": ["Slope tibiale mediale e cartilagine. Uno studio caso-controllo del Journal of ISAKOS, della Charité di Berlino, ha misurato lo slope con il metodo di Dejour, da tre lettori in cieco, in duecentottanta pazienti con lesioni cartilaginee trattati con MACI, e lo ha confrontato con controlli accoppiati per età e sesso.", "I numeri. Slope mediale 9,73 gradi contro 8,92, differenza aggiustata 0,80 gradi, intervallo di confidenza 95% da 0,32 a 1,27. Per sede: retropatellare più 0,92, intervallo da 0,05 a 1,80; trocleare più 1,60, da 0,11 a 3,10; nessuna differenza per i condili.", "Il limite. Retrospettivo, livello III: associazione, non causalità. La differenza è piccola, con intervalli che sfiorano lo zero, e la popolazione è selezionata, solo MACI. Non dice che correggere lo slope protegga la cartilagine. Gli autori: rilevanza clinica incerta.\nFonte: PubMed, PMID 42829203."], "misto": ["Lo slope è l'inclinazione all'indietro del piatto tibiale. Uno studio di Berlino su duecentottanta pazienti con danni alla cartilagine, operati con un trapianto di cartilagine, ha confrontato lo slope con quello di controlli simili per età e sesso.", "Il valore medio è 9,73 gradi nei pazienti e 8,92 nei controlli, cioè 0,8 gradi di differenza, con un intervallo di incertezza da 0,32 a 1,27. Il legame c'è per i danni dietro la rotula e nella troclea, non per quelli dei condili.", "Il limite: è un'associazione osservata a posteriori. Lo studio non dimostra che lo slope causi il danno né che correggerlo lo prevenga, e riguarda solo pazienti operati con questa tecnica. Il significato clinico resta incerto.\nFonte: PubMed, PMID 42829203."], "pazienti": ["Il piatto della tibia su cui poggia il femore è inclinato all'indietro: si chiama slope. Un gruppo di Berlino lo ha misurato in duecentottanta persone con danni alla cartilagine e in persone simili senza il danno.", "In media è di 9,73 gradi nelle prime e 8,92 nelle seconde: meno di un grado di differenza. Il legame c'è per i danni dietro la rotula e nell'incavo in cui scorre, non per le altre zone.", "È una piccola differenza e non dimostra che sia la causa del danno. Lo studio non dice che cosa convenga fare: se ci sono dubbi, conviene parlarne con il proprio ortopedico.\nFonte: PubMed, PMID 42829203."]}, "linkedin": {"chir": ["Slope tibiale mediale e cartilagine (Journal of ISAKOS, ottobre 2026): caso-controllo di livello III su 280 pazienti trattati con MACI, Charité Berlino. MPTS 9,73° contro 8,92°, differenza aggiustata 0,80° (IC 95% 0,32-1,27).", "Per sede: retropatellare +0,92° (IC 95% 0,05-1,80), trocleare +1,60° (IC 95% 0,11-3,10); condili senza differenza. ICC fra lettori 0,921.", "Limite: retrospettivo, associazione e non causalità; differenza piccola, intervalli vicini allo zero; solo pazienti MACI. Nessun dato sulla correzione dello slope.\nFonte: PubMed, PMID 42829203."], "misto": ["Slope tibiale e danni alla cartilagine: uno studio di Berlino su 280 pazienti operati con trapianto di cartilagine li confronta con controlli simili per età e sesso. Slope medio 9,73 gradi contro 8,92, differenza di 0,8 gradi (intervallo di incertezza da 0,32 a 1,27).", "Il legame è presente per le lesioni dietro la rotula e nella troclea, non per quelle dei condili.", "Limite: associazione osservata a posteriori, non prova di causa; la differenza è piccola e la rilevanza clinica resta incerta.\nFonte: PubMed, PMID 42829203."], "pazienti": ["Pendenza del piatto tibiale e danni alla cartilagine: uno studio di Berlino su 280 persone con danni alla cartilagine del ginocchio.", "La pendenza è in media di 9,73 gradi contro 8,92 in persone simili senza il danno; la differenza si vede dietro la rotula e nell'incavo in cui scorre, non nelle altre zone.", "È una differenza molto piccola e non dimostra che sia la causa. Per dubbi, conviene parlarne con il proprio ortopedico.\nFonte: PubMed, PMID 42829203."]}, "instagram": {"chir": ["Slope mediale 9,73° contro 8,92° nei pazienti MACI (280): differenza aggiustata 0,80°, IC 95% 0,32-1,27. Solo retropatellare e trocleare.", "Livello III, associazione.", "Rilevanza clinica incerta.\nFonte: PubMed, PMID 42829203."], "misto": ["Slope e cartilagine: su 280 pazienti la pendenza del piatto tibiale è 9,73 gradi contro 8,92 nei controlli, solo per rotula e troclea.", "È un'associazione osservata a posteriori, non una prova di causa.", "Rilevanza clinica incerta.\nFonte: PubMed, PMID 42829203."], "pazienti": ["Pendenza del piatto tibiale e cartilagine: una piccola differenza, meno di un grado, in 280 persone studiate a Berlino.", "Il legame c'è per la zona dietro la rotula, non per le altre.", "Non dimostra una causa: se ci sono dubbi, se ne parla con il proprio ortopedico.\nFonte: PubMed, PMID 42829203."]}, "reel": {"chir": ["Slope mediale e cartilagine: c'è un legame?", "280 pazienti MACI: 9,73° contro 8,92°, differenza 0,80° (IC 95% 0,32-1,27), solo rotula e troclea.", "Associazione, livello III: non dice niente sulla correzione."], "misto": ["Pendenza del piatto tibiale e cartilagine: c'è un legame?", "280 persone: 9,73 gradi contro 8,92, solo dietro la rotula e nella troclea.", "Associazione, non causa: significato clinico incerto."], "pazienti": ["Pendenza della tibia e danni alla cartilagine: c'è un legame?", "Uno studio su 280 persone vede una piccola differenza, solo dietro la rotula.", "Non dimostra una causa: se ne parla con lo specialista."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #Cartilagine #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #cartilagine #slopetibiale #chirurgiaortopedica #medicinadellosport #ortopediaticino #medicinabasatasulleprove #traumatologiadellosport", "kw": "slope tibiale, cartilagine del ginocchio, lesione cartilaginea rotula"}};

var NLB={"1": {"prof": ["Slope tibiale mediale e lesioni cartilaginee: associazione solo per rotula e troclea", "Uno studio caso-controllo del Journal of ISAKOS (Charité, ottobre 2026) su 280 pazienti con lesione cartilaginea trattati con MACI riporta uno slope mediale di 9,73° contro 8,92° nei controlli accoppiati: differenza aggiustata 0,80° (IC 95% 0,32-1,27). Per sede, +0,92° per le lesioni retropatellari (IC 95% 0,05-1,80) e +1,60° per le trocleari (IC 95% 0,11-3,10); nessuna differenza per i condili. Affidabilità fra lettori ICC 0,921.", "Nota critica: studio retrospettivo di livello III, solo associazione; la differenza è piccola, con intervalli che sfiorano lo zero; popolazione selezionata (solo MACI); non dice niente sulla correzione dello slope né sulla prevenzione."], "mix": ["Pendenza del piatto tibiale e cartilagine: una relazione piccola e limitata a rotula e troclea", "Uno studio su 280 persone con danno alla cartilagine del ginocchio, operate con una tecnica di trapianto di cartilagine, ha misurato l'inclinazione all'indietro del piatto tibiale sul lato interno, lo slope. In media è 9,73 gradi contro 8,92 in persone simili per età e sesso senza questo danno: circa 0,8 gradi di differenza. Il legame c'è per le lesioni dietro la rotula e nella troclea, non per quelle dei condili.", "Nota sul limite: è un'associazione osservata a posteriori, la differenza è piccola e lo studio non dice se lo slope causi il danno né se correggerlo lo prevenga; gli autori stessi giudicano incerta la rilevanza clinica."], "paz": ["Inclinazione del piatto tibiale e danni alla cartilagine: una piccola associazione, da non sovrainterpretare", "Alcuni ricercatori di Berlino hanno confrontato 280 persone con danni alla cartilagine del ginocchio con altre di pari età e sesso. Chi ha il danno dietro la rotula o nell'incavo in cui scorre la rotula ha in media un piatto tibiale inclinato di meno di un grado in più. Per le altre zone del ginocchio non c'è differenza.", "È una differenza molto piccola e non dimostra che sia la causa del danno: lo studio guarda indietro nel tempo e non dice che cosa convenga fare. Resta una questione da valutare con il proprio ortopedico, caso per caso."], "kw": "slope tibiale, cartilagine del ginocchio, lesione cartilaginea rotula"}, "2": {"prof": ["Legamento crociato posteriore negli atleti d'élite: tutore dinamico nelle lesioni isolate acute selezionate", "Una rassegna narrativa di 51 studi (Indian Journal of Orthopaedics) sul crociato posteriore negli atleti d'élite riporta un rientro allo sport superiore al 90% con tutore dinamico precoce e rieducazione centrata sul quadricipite nelle lesioni acute isolate selezionate di grado II-III (livello III), e un rientro fra l'80 e il 90% nelle multilegamentose; il ritorno alla performance piena è meno frequente. Dimensioni dell'effetto e intervalli non riportati nell'abstract.", "Nota critica: rassegna narrativa di livello V, senza meta-analisi; il rientro >90% vale per coorti selezionate; fascio singolo, doppio fascio e inlay tibiale mostrano vantaggi biomeccanici ma clinici limitati secondo gli autori, senza numeri nell'abstract."], "mix": ["Crociato posteriore e sport di alto livello: in casi scelti il tutore e la riabilitazione permettono il rientro", "Una rassegna di 51 studi ha raccolto i dati sul legamento crociato posteriore negli atleti professionisti. Nelle lesioni recenti, isolate e di grado medio-alto, in persone selezionate, il rientro allo sport supera il 90% con un tutore dinamico e un lavoro sul quadricipite; nelle lesioni di più legamenti il rientro è fra l'80 e il 90%, ma tornare al livello di prestazione di prima è meno frequente.", "Nota sul limite: è una rassegna senza calcolo statistico complessivo, basata in parte su gruppi selezionati; non indica una tecnica chirurgica dimostrata superiore e i dati specifici per sport restano pochi."], "paz": ["Lesione del crociato posteriore negli sportivi: spesso si parte da tutore e riabilitazione", "Una rassegna di 51 studi sugli atleti di alto livello con lesione del legamento crociato posteriore indica che, nelle lesioni recenti e senza altri legamenti coinvolti, in persone scelte, la maggior parte torna allo sport con un tutore e un lavoro sul muscolo della coscia. Quando sono coinvolti più legamenti, tornare allo sport è comune ma tornare al livello di prima è meno frequente.", "I dati sono limitati e le persone studiate sono selezionate: la scelta fra tutore e intervento dipende dal singolo caso e dalla valutazione dello specialista."], "kw": "legamento crociato posteriore, lesione LCP, ritorno allo sport"}, "3": {"prof": ["MPFL con cordone di retinacolo mediale: nota di tecnica senza pazienti né esiti", "Una nota di tecnica (Arthroscopy Techniques, settembre 2026) descrive la ricostruzione del MPFL combinata con un cordone longitudinale di retinacolo patellare mediale, di 1 cm, lasciato attaccato prossimalmente al tendine quadricipitale, al posto del legamento quadricipito-femorale mediale; l'innesto tendineo del MPFL viene fissato insieme all'estremità libera del cordone. Nessun dato clinico riportato nell'abstract.", "Nota critica: livello V, nessun paziente, nessun follow-up; «efficace» è un'affermazione degli autori; nessun confronto con la ricostruzione isolata del MPFL o a doppio fascio."], "mix": ["Rotula che esce dalla sede: una variante chirurgica descritta, ancora senza dati sui pazienti", "Un gruppo cinese descrive un modo di rinforzare l'operazione per la rotula che esce ripetutamente dalla sede: oltre al legamento ricostruito con un tendine, usa una striscia di tessuto laterale alla rotula, già presente e lasciata attaccata, che viene fissata insieme al tendine.", "Nota sul limite: è la descrizione di una tecnica, senza pazienti né risultati; non si può dire se funzioni meglio di altre."], "paz": ["Rotula instabile: descritta una variante di intervento, ma non ci sono ancora risultati", "Chirurghi cinesi hanno pubblicato la descrizione di una variante dell'intervento per la rotula che esce più volte dalla sua sede. Si ricostruisce il legamento che la trattiene e si aggiunge una striscia di tessuto vicino alla rotula.", "È solo la descrizione di come si esegue: non vengono riportati pazienti né risultati. Per ora non permette di dire se sia utile; la scelta della tecnica spetta al chirurgo."], "kw": "instabilità rotulea, legamento femororotuleo mediale, rotula che esce dalla sede"}, "4": {"prof": ["Protesi monocompartimentale: allineamento radiografico equivalente con o senza robot imageless", "Uno studio retrospettivo monocentrico (Archives of Orthopaedic and Trauma Surgery, ottobre 2026) su 96 UKA mediali consecutive confronta tre gruppi (NAVIO 38, strumentario convenzionale 27, CORI 31): HKA postoperatorio 177,1° ± 2,1°, 177,3° ± 2,5° e 177,7° ± 2,2° (p=0,56); angoli coronali di femore e tibia senza differenze; tutti i casi entro le zone di sicurezza.", "Nota critica: gruppi di 27-38 con due modelli di impianto, quindi robot e protesi sono confusi; solo misure radiografiche, nessun esito clinico né di sopravvivenza; «nessuna differenza» non è prova di equivalenza."], "mix": ["Protesi di una parte del ginocchio: la posizione dei componenti è simile con e senza robot", "Un centro italiano ad alto volume ha confrontato la posizione dei componenti in 96 protesi di una sola parte del ginocchio, messe con due sistemi robotici o con gli strumenti tradizionali. L'allineamento della gamba dopo l'operazione è risultato simile nei tre gruppi (circa 177 gradi) e tutti i casi erano dentro i margini considerati sicuri.", "Nota sul limite: i gruppi sono piccoli, gli impianti non sono gli stessi e si misura solo il posizionamento sulle radiografie, non come stanno i pazienti dopo l'intervento."], "paz": ["Protesi parziale del ginocchio: con o senza robot, i componenti risultano ben posizionati", "Un ospedale italiano ha controllato sulle radiografie dopo l'intervento la posizione di 96 protesi che sostituiscono una sola parte del ginocchio, impiantate con o senza assistenza robotica. In tutti i gruppi la posizione era corretta e simile.", "Lo studio guarda solo le radiografie e non come stanno i pazienti nel tempo: non permette di dire se un metodo dia risultati migliori per chi viene operato."], "kw": "protesi monocompartimentale, protesi parziale ginocchio, robot chirurgia"}, "5": {"prof": ["Protesi totale robotica contro manuale: CRP e perdita ematica minori al terzo giorno, tempi più lunghi", "Uno studio retrospettivo monocentrico (Journal of Robotic Surgery, settembre 2026) su 106 protesi totali (robotica 48, manuale 58) con IPTW riporta, per la tecnica robotica, deviazione HKA minore, CRP e VAS più bassi al terzo giorno, articolarità maggiore e minore perdita ematica stimata, ma tempi operatori e di laccio più lunghi e un rapporto neutrofili/linfociti più alto. Valori numerici e intervalli non riportati nell'abstract.", "Nota critica: retrospettivo non randomizzato; esiti a tre giorni, nessun esito funzionale a distanza né di sopravvivenza; sistema robotico non nominato; il significato clinico dell'NLB più alto resta incerto."], "mix": ["Protesi totale con robot: nei primi giorni meno infiammazione e meno perdita di sangue, ma l'intervento dura di più", "Un ospedale cinese ha confrontato 106 protesi totali di ginocchio, 48 con assistenza robotica e 58 con la tecnica manuale. Nel gruppo robotico l'allineamento della gamba era più vicino al valore ideale, la proteina che indica infiammazione era più bassa al terzo giorno, la perdita di sangue stimata minore, ma l'operazione richiedeva più tempo.", "Nota sul limite: lo studio guarda indietro nel tempo e osserva solo i primi giorni; non dice quale robot sia stato usato né come stanno i pazienti dopo mesi o anni."], "paz": ["Protesi di ginocchio con robot: qualche differenza nei primi giorni, da confermare nel tempo", "Uno studio su 106 persone operate di protesi totale di ginocchio, con o senza robot, ha trovato nel gruppo con robot meno infiammazione e meno perdita di sangue al terzo giorno, a fronte di un intervento più lungo.", "Sono differenze nei primi giorni: lo studio non dice se i risultati a distanza siano diversi. La scelta della tecnica spetta al chirurgo, in base al singolo caso."], "kw": "protesi totale ginocchio, chirurgia robotica, recupero dopo protesi"}, "6": {"prof": ["UKA: la confezione di cemento da 20 g riduce lo spreco senza cambiare la fissazione a un anno", "Un RCT monocentrico (Indian Journal of Orthopaedics) su 198 UKA mediali (40 g in 98, 20 g in 100) riporta lo stesso cemento usato (circa 8,1 g; p=0,173) e uno spreco di 85,76% contro 71,49% (p<0,001); penetrazione, linee radiolucenti (circa 18-20%) ed estrusione (circa 12-18%) comparabili; sopravvivenza a un anno 100% e 99,0% (p>0,3), con un'infezione trattata con DAIR nel gruppo 40 g.", "Nota critica: follow-up di un anno, un solo centro; un solo evento infettivo, quindi il confronto di sicurezza è muto (RR 3,06; IC 95% 0,13-74,24); il risparmio dipende dai prezzi dell'istituto."], "mix": ["Protesi di una parte del ginocchio: una confezione di cemento più piccola riduce lo spreco", "In uno studio su 198 persone operate di protesi di una sola parte del ginocchio, con confezioni di cemento da 20 o da 40 grammi, la quantità effettivamente usata è stata la stessa, circa 8 grammi, ma con la confezione piccola si è buttato via meno cemento. La tenuta della protesi alle radiografie a un anno è risultata simile.", "Nota sul limite: lo studio dura un anno e viene da un solo centro; gli eventi gravi sono troppo rari per confrontarli; non dice niente sui risultati a lungo termine."], "paz": ["Protesi parziale di ginocchio: usare meno cemento da buttare, con una tenuta simile a un anno", "Un ospedale cinese ha confrontato due confezioni di cemento per fissare una protesi che sostituisce una parte del ginocchio. La quantità usata è stata uguale; con la confezione più piccola se ne è sprecato meno. A un anno la tenuta era simile.", "È uno studio breve e di un solo centro: riguarda soprattutto i materiali, non il recupero dei pazienti, e non permette di dire niente sulla durata della protesi."], "kw": "protesi monocompartimentale, cemento osseo, protesi parziale ginocchio"}, "7": {"prof": ["Meniscectomia parziale: needlescope da 1,9 mm e ottica da 4 mm, costi ed esiti senza differenze a un anno", "Un'analisi retrospettiva su dati prospettici (Arthroscopy, Sports Medicine, and Rehabilitation, ottobre 2026) su 24 pazienti per gruppo, follow-up medio 26 mesi, riporta un miglioramento IKDC di 58,7 con needlescope contro 48,7 con ottica standard (p=0,24) e della VAS di 5,4 contro 4,5 (p=0,55); costo per caso 17.236,69 contro 16.994,00 dollari (p=0,26); rapporto incrementale di costo-efficacia 367,71 dollari per QALY.", "Nota critica: 24 pazienti per gruppo, un solo chirurgo e un solo centro; assegnazione ai gruppi non descritta; l'assenza di differenza non è prova di equivalenza; intervalli di confidenza non riportati."], "mix": ["Meniscectomia parziale: un artroscopio sottilissimo non cambia costi ed esiti in un piccolo studio", "Uno studio su 48 pazienti operati di asportazione parziale del menisco ha confrontato un artroscopio sottile, da 1,9 millimetri, con quello standard da 4. A un anno e oltre, miglioramento del dolore e della funzione e costi sono risultati simili.", "Nota sul limite: pochi pazienti, un solo chirurgo, un solo centro; uno studio così non può escludere differenze reali, anche se non le ha trovate."], "paz": ["Intervento al menisco con un artroscopio più sottile: risultati e costi simili in un piccolo studio", "In 48 pazienti operati per asportazione parziale del menisco, l'uso di uno strumento di visione più sottile ha dato risultati e costi simili a quello abituale.", "Il gruppo studiato è piccolo e viene da un solo chirurgo: i risultati non bastano a dire che uno strumento sia da preferire. La scelta spetta al chirurgo."], "kw": "menisco, meniscectomia parziale, artroscopia del ginocchio"}, "8": {"prof": ["Calciatrici adolescenti ad alto rischio: il momento di abduzione del ginocchio resta ridotto a sei mesi", "Un'analisi secondaria di un RCT (JOSPT, ottobre 2026) su 150 calciatrici adolescenti in un programma neuromuscolare di 6 settimane riporta, nel gruppo ad alto rischio (44), un KAM da -37,5 ± 9,0 N·m a -25,2 ± 11,4 dopo il programma e -29,4 ± 14,5 a sei mesi; nessuna variazione nel gruppo a basso rischio (87). Interazione rischio-sessione p<0,001.", "Nota critica: stratificazione post hoc sulla misura basale, possibile regressione verso la media; endpoint di laboratorio, non lesioni del LCA; differenze fra i tre gruppi di biofeedback non riportate nell'abstract."], "mix": ["Prevenzione del LCA nelle calciatrici: il movimento a rischio del ginocchio migliora e resta migliorato dopo sei mesi", "Nelle calciatrici adolescenti con un movimento di atterraggio considerato a rischio per il legamento crociato, un programma di allenamento neuromuscolare di sei settimane ha ridotto il carico che tende a portare il ginocchio verso l'interno, e la riduzione era ancora presente sei mesi dopo. Nelle atlete a basso rischio il valore non è cambiato.", "Nota sul limite: si misura il movimento in laboratorio, non quanti infortuni vengono evitati; l'analisi è stata fatta dopo la divisione in gruppi e il miglioramento può in parte dipendere da quella divisione."], "paz": ["Giovani calciatrici: un allenamento specifico migliora l'atterraggio e il miglioramento resta dopo sei mesi", "In giovani calciatrici con un modo di atterrare che carica troppo il ginocchio, sei settimane di allenamento specifico hanno ridotto quel carico, e il miglioramento era ancora presente a sei mesi.", "Lo studio misura il movimento in laboratorio, non gli infortuni: non dimostra che il crociato sia meglio protetto. Per un programma adatto conviene parlarne con lo specialista."], "kw": "prevenzione LCA, calciatrici, allenamento neuromuscolare"}};

var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J ISAKOS",h:"Slope tibiale mediale più ripido nelle lesioni cartilaginee femororotulee, non in quelle dei condili",v:"Caso-controllo su 280 pazienti con lesione cartilaginea trattati con MACI: slope mediale 9,73° contro 8,92° nei controlli (differenza aggiustata 0,80°; IC 95% 0,32-1,27). L'associazione tiene per rotula e troclea, non per i condili; la rilevanza clinica resta incerta.",ax:"Oehme, Arteaga, El-Kayali, Wolf, Bartek, Gwinner, Winkler, Jung, Milinkovic",date:"ott 2026",meta:"studio caso-controllo retrospettivo accoppiato, 280 pazienti con lesione cartilaginea trattati con MACI, Charité Berlino · [III]",pmid:'42829203',doi:'10.1016/j.jisako.2026.101228',journal:"Journal of ISAKOS: joint disorders & orthopaedic sports medicine",authors:"Oehme S, Arteaga J, El-Kayali M, Wolf F, Bartek B, Gwinner C, Winkler T, Jung T, Milinkovic DD",design:"Studio caso-controllo retrospettivo accoppiato (livello III), centro universitario unico (Charité, Berlino), 09/2013-02/2024: 501 pazienti con lesioni cartilaginee del ginocchio trattati con MACI, 280 inclusi dopo i criteri di eleggibilità. Slope mediale (MPTS) misurato con il metodo di Dejour da tre lettori in cieco (media dei tre). Analisi primaria con modelli lineari a effetti misti (età, sesso, struttura degli insiemi accoppiati); t-test non accoppiati con d di Cohen come sensibilità; confronti per sede con correzione per test multipli.",pop:"280 pazienti con lesioni cartilaginee operati con MACI, accoppiati 1:1 per età e sesso a controlli (provenienza dei controlli non riportata nell'abstract). Per sede, con accoppiamento molti-a-uno: retropatellare 100 contro 200, trocleare 34 contro 68, condilo mediale 73 contro 146, condilo laterale 36 contro 72.",results:"MPTS 9,73° nel gruppo MACI contro 8,92° nei controlli: differenza aggiustata 0,80° (IC 95% 0,32-1,27; p<0,01). Affidabilità fra lettori ICC 0,921. Per sede: retropatellare +0,92° (IC 95% 0,05-1,80; p aggiustato 0,03); trocleare +1,60° (IC 95% 0,11-3,10; p aggiustato 0,03); condilo mediale +0,15° (IC 95% da -0,87 a 1,17; p aggiustato 0,99); condilo laterale +1,01° (IC 95% da -0,44 a 2,46; p aggiustato 0,29). Le analisi di sensibilità non aggiustate concordano.",concl:"Gli autori: uno slope mediale maggiore si associa a lesioni cartilaginee del comparto femororotuleo ma non dei condili femorali, quindi la relazione sarebbe specifica per comparto; la rilevanza clinica resta incerta.",limits:"Differenza di 0,8° in media: piccola in assoluto, con intervalli che per rotula e troclea sfiorano lo zero (limite inferiore 0,05° e 0,11°) · un ICC di 0,921 misura quanto i lettori concordano, non se 0,8° conti per il paziente · retrospettivo e solo associativo: non dice se lo slope causi la lesione né se correggerlo la prevenga · solo pazienti poi operati con MACI (selezione), provenienza dei controlli non riportata · testo non su PMC: numeri dall'abstract, non dal testo.",perte:"Slope e cartilagine sono due tuoi temi (osteotomie di slope; AMIC e minced cartilage). Qui i pazienti sono stati trattati con MACI, non con AMIC né AutoCart, e non c'è nessuna osteotomia: lo studio non dice che correggere lo slope protegga la cartilagine. Non muove nessuna tensione: T1a riguarda lo slope come fattore di fallimento del LCA con LET, qui il risultato riguarda la cartilagine."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Indian Journal of Orthopaedics",h:"LCP negli atleti d'élite: tutore dinamico e rientro in casi selezionati",v:"Rassegna narrativa di 51 studi: nelle lesioni acute isolate selezionate di grado II-III il rientro supera il 90% con tutore dinamico e rieducazione del quadricipite (livello III); nelle multilegamentose con LCP il rientro è fra l'80 e il 90%. Nessuna meta-analisi, nessun intervallo riportato.",ax:"Elliott, Gupte",date:"mag 2026 (in PubMed da ott)",meta:"rassegna narrativa, 51 studi inclusi, atleti d'élite con lesione del LCP isolata o multilegamentosa · [V]",pmid:'42824238',doi:'10.1007/s43465-026-01794-2',journal:"Indian Journal of Orthopaedics",authors:"Elliott DA, Gupte CM",design:"Rassegna narrativa su PubMed ed Embase (dall'origine ad aprile 2025) con screening delle bibliografie; priorità agli studi clinici con esiti di rientro allo sport dopo trattamento operatorio o non operatorio di lesioni isolate del LCP e di multilegamentose con LCP in atleti. 51 studi inclusi; l'eterogeneità ha escluso la meta-analisi. Livello V.",pop:"Atleti, per lo più d'élite, con lesione isolata del LCP o multilegamentosa con LCP; 51 studi, numero di pazienti non riportato nell'abstract.",results:"Lesioni isolate del LCP rare nei calciatori d'élite; le multilegamentose con LCP più frequenti negli sport di contatto. Tutore dinamico precoce con rieducazione centrata sul quadricipite: rientro >90% in coorti selezionate di lesioni acute isolate di grado II-III (livello III). Multilegamentose nelle coorti d'élite recenti: rientro 80-90%, ma il ritorno alla performance piena è meno frequente. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la gestione del LCP nell'atleta d'élite richiede decisioni individuali e specifiche per lo sport; i dati di alta qualità, specifici per sport, restano limitati.",limits:"Rassegna narrativa, livello V: la sintesi dipende dalla scelta degli studi · >90% di rientro è riferito a coorti selezionate e al «rientro», non alla performance piena · ricostruzione a fascio singolo, doppio fascio e inlay tibiale: vantaggi biomeccanici ma clinici limitati secondo gli autori, senza numeri nell'abstract · testo completo su PMC (PMC13627502) non aperto oggi: numeri dall'abstract.",perte:"Il LCP e le multilegamentose sono fra le tue ricostruzioni. La rassegna non dice quale innesto o quale tecnica: non porta dati sul retto femorale né sul tuo uso del LCP; è un quadro d'insieme sul trattamento non operatorio contro operatorio. Non muove nessuna tensione."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy Techniques",h:"MPFL più cordone del retinacolo mediale al posto del legamento quadricipito-femorale",v:"Nota di tecnica per la rotula recidivante: il cordone longitudinale di retinacolo mediale sostituisce il legamento quadricipito-femorale mediale e si associa alla ricostruzione del MPFL con innesto tendineo. Nessun paziente, nessun esito: descrive, non dimostra.",ax:"Dai, Yang, Jiang, Chen",date:"set 2026",meta:"nota di tecnica chirurgica (Arthroscopy Techniques), nessun paziente riportato nell'abstract · [V]",pmid:'42812676',doi:'10.1002/atn2.70282',journal:"Arthroscopy Techniques",authors:"Dai Z, Yang Z, Jiang X, Chen D",design:"Nota di tecnica: ricostruzione del MPFL combinata con il cordone di retinacolo patellare mediale (striscia longitudinale di 1 cm, dissecata dall'estremità distale e lasciata attaccata prossimalmente all'inserzione del tendine quadricipitale) al posto del legamento quadricipito-femorale mediale. L'innesto tendineo del MPFL viene fissato insieme all'estremità libera del cordone; vasto mediale obliquo e retinacolo residuo vengono suturati alla rotula, con tensionamento mediale.",pop:"Nessuna popolazione: la nota non riporta pazienti nell'abstract.",results:"Nessun risultato clinico, radiologico o biomeccanico nell'abstract. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori la presentano come strategia chirurgica facilmente adottabile ed efficace per la rotula recidivante.",limits:"Livello V: nessun paziente, nessun esito, nessun follow-up · «efficace» è un'affermazione degli autori, non misurata nell'abstract · non è un confronto con la ricostruzione isolata del MPFL né con quella a doppio fascio · testo ad accesso aperto su PMC (PMC13621365) non aperto oggi: solo l'abstract.",perte:"Il MPFL con ancore FiberTak onlay è fra i tuoi interventi. Qui il costrutto è diverso (innesto tendineo più cordone di retinacolo, fissazione non descritta nell'abstract) e non c'è alcun dato: è un'idea di tecnica, non una prova. Non muove nessuna tensione."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Archives of Orthopaedic and Trauma Surgery",h:"Protesi monocompartimentale: posizionamento radiografico uguale con o senza robot imageless",v:"Coorte retrospettiva monocentrica su 96 UKA mediali (robot imageless NAVIO 38, strumentario convenzionale 27, robot CORI 31): HKA 177,1° ± 2,1°, 177,3° ± 2,5°, 177,7° ± 2,2° (p=0,56); tutte le componenti entro le zone di sicurezza. Centro ad alto volume con filosofia di allineamento costante.",ax:"Montagna, Andriollo, Cinelli, Marescalchi, Matascioli, Benazzo, Rossi",date:"ott 2026",meta:"studio retrospettivo comparativo monocentrico, 96 UKA mediali consecutive in 3 gruppi · [III]",pmid:'42828545',doi:'10.1007/s00402-026-06499-7',journal:"Archives of Orthopaedic and Trauma Surgery",authors:"Montagna A, Andriollo L, Cinelli V, Marescalchi M, Matascioli L, Benazzo F, Rossi SMP",design:"Studio retrospettivo comparativo su 96 UKA mediali consecutive in un unico istituto ad alto volume (Fondazione Poliambulanza, Brescia): Journey I con robot imageless NAVIO (38), Journey II Uni con strumentario convenzionale (27), Journey II UK con robot imageless CORI (31). Radiografie in carico dell'arto intero pre e postoperatorie: angolo anca-ginocchio-caviglia (HKA), angoli coronali di femore (FCCA) e tibia (TCCA), parametri sagittali; allineamento tibiale secondo la filosofia metafisaria di Cartier.",pop:"96 UKA mediali consecutive, tre gruppi di 38, 27 e 31; caratteristiche demografiche e parametri radiografici preoperatori comparabili (tutti p>0,05).",results:"HKA postoperatorio 177,1° ± 2,1° (NAVIO), 177,3° ± 2,5° (convenzionale), 177,7° ± 2,2° (CORI): p=0,56. Angoli coronali di femore e tibia senza differenze significative; parametri sagittali comparabili. Tutti i casi dei tre gruppi dentro le zone di sicurezza predefinite per HKA, FCCA e TCCA. Intervalli di confidenza delle differenze non riportati nell'abstract.",concl:"Gli autori: in un centro ad alto volume con una filosofia di allineamento costante, la UKA mediale raggiunge un posizionamento radiografico equivalente e molto accurato con o senza assistenza robotica.",limits:"Retrospettivo, tre gruppi di 27-38 pazienti con impianti diversi (due modelli di protesi): robot e impianto sono confusi · misura solo radiografica, nessun esito clinico, funzionale o di sopravvivenza dell'impianto · «nessuna differenza» con questi numeri non è prova di equivalenza (vedi studio muto) · i robot NAVIO e CORI non sono il tuo VELYS.",perte:"Fai protesi monocompartimentale e totale con VELYS: qui i robot sono altri, imageless, e il risultato è radiografico. Tocca il tema della robotica senza dire niente sul VELYS né su esiti clinici. Non muove nessuna tensione."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"Protesi totale robotica contro manuale: meno infiammazione al terzo giorno, tempi operatori più lunghi",v:"Coorte retrospettiva monocentrica su 106 protesi totali (robot 48, manuale 58), con ponderazione IPTW: con il robot allineamento HKA più vicino a 180°, CRP al terzo giorno più basso, perdita ematica stimata minore, ma tempi operatori più lunghi e NLB più alto. Valori numerici non riportati nell'abstract.",ax:"Tao, Xia, Gao",date:"set 2026",meta:"studio retrospettivo comparativo monocentrico, 106 protesi totali di ginocchio (48 robotiche, 58 manuali) · [III]",pmid:'42814176',doi:'10.1007/s11701-026-04007-y',journal:"Journal of Robotic Surgery",authors:"Tao M, Xia W, Gao W",design:"Studio retrospettivo comparativo (Hefei, Cina) su 106 pazienti con gonartrosi sottoposti a protesi totale primaria monolaterale: 48 con assistenza robotica (RA-TKA) e 58 con tecnica manuale convenzionale (CM-TKA). Rilevati tempi operatori e di laccio, HKA, CRP, rapporto neutrofili/linfociti (NLB), emoglobina, VAS e articolarità; perdita ematica totale stimata con le formule di Nadler e Gross. Regressione multivariata e ponderazione con probabilità inversa di trattamento stabilizzata (IPTW).",pop:"106 pazienti con gonartrosi, protesi totale primaria monolaterale: 48 RA-TKA, 58 CM-TKA. Sistema robotico non riportato nell'abstract.",results:"Con RA-TKA: tempi operatorio e di laccio più lunghi; perdita ematica stimata minore; HKA più vicino a 180° e deviazione HKA minore; tassi di outlier e correzione HKA simili; CRP al terzo giorno più basso, VAS al terzo giorno più bassa, articolarità al terzo giorno maggiore; NLB più alto al primo e al terzo giorno. Dopo l'aggiustamento restano associati a RA-TKA: deviazione HKA minore, CRP più basso, minore perdita ematica, VAS più bassa, articolarità maggiore, NLB più alto. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: RA-TKA si associa a CRP del terzo giorno più basso, minore perdita ematica e a differenze nel dolore e nell'articolarità precoci, con tempi più lunghi; NLB e CRP hanno andamenti discordanti e il significato clinico dell'NLB più alto resta incerto.",limits:"Retrospettivo, non randomizzato: l'IPTW corregge solo ciò che è misurato · esiti a tre giorni: nessun esito funzionale a distanza né di sopravvivenza dell'impianto · il sistema robotico non è nominato nell'abstract: non si sa se sia il tuo VELYS · valori numerici e intervalli assenti nell'abstract.",perte:"Fai protesi totale con VELYS. L'abstract non dice quale robot: non si può trasferire al tuo sistema. I segnali (meno CRP, meno perdita ematica) sono precoci e di laboratorio; il quadro più solido sulla robotica resta il registro NJR del 1 ottobre (HR di revisione 1,03; IC 95% 0,86-1,26). Non muove nessuna tensione."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Indian Journal of Orthopaedics",h:"Protesi monocompartimentale: il cemento da 20 g spreca meno del 40 g, con fissazione uguale",v:"RCT monocentrico su 198 UKA mediali (confezione da 40 g in 98, da 20 g in 100): cemento usato uguale (circa 8,1 g), spreco 85,76% contro 71,49% (p<0,001); linee radiolucenti, estrusione e sopravvivenza a un anno comparabili. Un'infezione trattata con DAIR nel gruppo 40 g (1/98 contro 0/100).",ax:"Lu, Xu, Feng, Xu, Wang, Wang",date:"giu 2026 (in PubMed da ott)",meta:"RCT prospettico monocentrico, 198 UKA mediali (40 g n=98, 20 g n=100), follow-up 1 anno · [I]",pmid:'42824616',doi:'10.1007/s43465-026-01849-4',journal:"Indian Journal of Orthopaedics",authors:"Lu Z, Xu Q, Feng Y, Xu Y, Wang X, Wang Q",design:"RCT prospettico monocentrico (Fu'an, Cina; 1 settembre 2022-30 giugno 2024): pazienti con UKA mediale assegnati a una confezione di cemento da 40 g (98) o da 20 g (100). Esiti: cemento usato, tasso di spreco, penetrazione, linee radiolucenti, estrusione e sopravvivenza dell'impianto a un anno (Kaplan-Meier, log-rank). Metodo di randomizzazione non riportato nell'abstract.",pop:"198 pazienti operati di UKA mediale senza difetti ossei rilevanti: 98 con confezione da 40 g, 100 con confezione da 20 g.",results:"Cemento usato simile (circa 8,1 g; p=0,173). Spreco 85,76% (40 g) contro 71,49% (20 g), p<0,001. Penetrazione circa 1,5 mm sul femore e 2,5 mm sulla tibia, linee radiolucenti circa 18-20%, estrusione circa 12-18%: comparabili. Un'infezione trattata con DAIR nel gruppo 40 g. Sopravvivenza a un anno 100% (20 g) contro 99,0% (40 g), p>0,3. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: nella UKA senza difetti ossei rilevanti l'uso di confezioni da 20 g riduce lo spreco con fissazione radiografica e risultati clinici a breve termine comparabili; con i prezzi dell'istituto, il risparmio stimato è sul costo del cemento.",limits:"Un anno di follow-up e un solo centro: niente sul fallimento asettico a lungo termine · eventi rari (1 infezione): il confronto di sicurezza è muto (vedi studio muto) · il risparmio dipende dai prezzi dell'istituto e dalla disponibilità di confezioni da 20 g · randomizzazione e cecità non riportate nell'abstract.",perte:"Fai UKA: è un dettaglio di tecnica e di costi, non di esito clinico. Il dato utile è che con circa 8 g di cemento a protesi la confezione da 40 g ne spreca la gran parte; il risultato non cambia fissazione né infezioni in modo dimostrabile. Non muove nessuna tensione."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Meniscectomia: ago-artroscopio da 1,9 mm o ottica da 4 mm, costi ed esiti simili",v:"Retrospettivo su dati prospettici (24 pazienti per gruppo, follow-up medio 26 mesi): miglioramento dell'IKDC 58,7 contro 48,7 (p=0,24) e della VAS 5,4 contro 4,5 (p=0,55); costo per caso 17.236,69 contro 16.994,00 dollari (p=0,26). Campione piccolo, un solo chirurgo, un solo centro.",ax:"Lubowitz, Lavender",date:"ott 2026",meta:"analisi economica retrospettiva su dati prospettici di un RCT più ampio, 24 contro 24 meniscectomie parziali, un solo chirurgo · [IV]",pmid:'42825169',doi:'10.1002/ars2.70112',journal:"Arthroscopy, Sports Medicine, and Rehabilitation",authors:"Lubowitz JH, Lavender C",design:"Revisione retrospettiva di dati raccolti in modo prospettico (da un RCT più ampio) su meniscectomie parziali di un solo chirurgo in una sola struttura (febbraio 2023-febbraio 2025): visualizzazione con needlescope chip-on-tip da 1,9 mm contro artroscopio standard a lenti con asta di vetro da 4 mm. Esiti: IKDC e VAS ad almeno un anno, costi, costo-efficacia (costo/QALY) e rapporto incrementale di costo-efficacia, con analisi di sensibilità.",pop:"24 pazienti per gruppo; età media 50 contro 46,5 anni (p=0,19); maschi 71% contro 46% (p=0,14); follow-up medio 26 mesi (12-36).",results:"Aumento IKDC 58,7 (needlescope) contro 48,7 (standard), p=0,24; miglioramento VAS 5,4 contro 4,5, p=0,55; costo medio per caso 17.236,69 contro 16.994,00 dollari, p=0,26. Costo-efficacia 1.177,32 contro 1.215,59 dollari per QALY; rapporto incrementale 367,71 dollari. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: nessuna differenza significativa di costo o esiti a un anno; entrambe le opzioni sono molto costo-efficaci (rapporto incrementale ben sotto la soglia di 50.000 dollari per QALY).",limits:"24 pazienti per gruppo, un chirurgo, un centro: il confronto è muto sugli esiti (vedi studio muto) · retrospettivo, assegnazione ai gruppi non descritta nell'abstract · costi e QALY di un solo sistema sanitario (dollari statunitensi) · dichiarazione dei conflitti di interesse non riportata nell'abstract.",perte:"La meniscectomia parziale è chirurgia che fai solo se serve, non il tuo nucleo (suture, radice, trapianto). Il dato non dice niente sulle suture meniscali. Non muove nessuna tensione."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Orthopaedic & Sports Physical Therapy",h:"Calciatrici ad alto rischio: il carico in abduzione del ginocchio resta ridotto a sei mesi",v:"Analisi secondaria di un RCT su 150 calciatrici adolescenti: nel gruppo ad alto rischio il momento di abduzione del ginocchio scende da -37,5 ± 9,0 N·m a -25,2 ± 11,4 dopo il programma neuromuscolare e resta a -29,4 ± 14,5 a sei mesi; nessun cambiamento nel gruppo a basso rischio. Misura di laboratorio, non infortuni.",ax:"Taylor, Hockenjos, Nguyen, Westbrook, Paterno, Pexa, Ford",date:"ott 2026",meta:"analisi secondaria di un RCT, 150 calciatrici adolescenti (131 analizzate: 87 a basso e 44 ad alto rischio), 6 mesi · [II]",pmid:'42823643',doi:'10.2519/jospt.2026.14125',journal:"The Journal of Orthopaedic & Sports Physical Therapy",authors:"Taylor JB, Hockenjos TJ, Nguyen AD, Westbrook AE, Paterno MV, Pexa BS, Ford KR",design:"Analisi secondaria di un RCT: 150 calciatrici adolescenti in un programma neuromuscolare (NMT) di 6 settimane, 3 volte la settimana, con biofeedback aumentato una volta la settimana, randomizzate a NMT più focus sull'anca, NMT più focus sul ginocchio o NMT con biofeedback finto. Analisi tridimensionale del movimento in drop vertical jump a inizio (PRE), subito dopo (POST) e a 6 mesi (RET). Stratificazione per momento di abduzione del ginocchio (KAM) basale in basso rischio (87; 12,7 ± 2,2 anni) e alto rischio (44; 14,0 ± 1,8 anni) secondo un valore soglia predefinito; ANOVA a disegno misto.",pop:"150 calciatrici adolescenti arruolate; 87 a basso rischio e 44 ad alto rischio nell'analisi (131 in totale).",results:"Interazione rischio-sessione significativa (p<0,001). Gruppo ad alto rischio, KAM: PRE -37,5 ± 9,0 N·m; POST -25,2 ± 11,4; RET -29,4 ± 14,5; riduzione significativa dal basale al post e dal basale ai 6 mesi. Gruppo a basso rischio: PRE -12,2 ± 6,2; POST -12,2 ± 7,6; RET -12,9 ± 8,7, nessuna variazione. Intervalli di confidenza delle differenze non riportati nell'abstract.",concl:"Gli autori: le atlete con biomeccanica del ginocchio ad alto rischio di lesione del LCA hanno migliorato il KAM con il programma neuromuscolare, e il cambiamento resta a sei mesi.",limits:"Analisi secondaria con stratificazione post hoc sulla misura basale: il guadagno nel gruppo ad alto rischio può includere regressione verso la media · endpoint di laboratorio (KAM in un salto), non lesioni del LCA · sei mesi, adolescenti: non dice niente sulle atlete operate di LCA · le differenze fra i tre gruppi di biofeedback non sono riportate nell'abstract.",perte:"Prevenzione primaria: non riguarda la chirurgia ricostruttiva che fai tu, ma è il lato del LCA più discusso con le famiglie di giovani atlete (dai 14 anni in su sei dentro la tua casistica). Nessun dato su infortuni evitati. Non muove nessuna tensione."}];

var SUGGQ=[{"k": "kol", "n": "C. M. Gupte (Londra, Regno Unito)", "w": "Londra, Regno Unito — coautore della rassegna narrativa di oggi sul legamento crociato posteriore negli atleti d'élite (PMID 42824238, afferenza letta nei metadati PubMed: Department of Orthopaedic Surgery and Sports Medicine, Londra); corrispondenza tecnica con la tua ricostruzione del LCP e le multilegamentose. Sostituisce T. Matsushita (3 ottobre, nessun segnale dell'utente arrivato per farlo ruotare)."}];

var BRIEF_TEXT="Oggi è domenica: prima la settimana, poi il giorno. Tra il 28 settembre e il 3 ottobre cinque lavori contano. Un'ampia coorte di trecento revisioni del crociato anteriore associa l'aumento laterale a una sopravvivenza dell'innesto a cinque anni del 90,6% contro il 79,9%, con hazard ratio 0,46 e intervallo di confidenza da 0,28 a 0,74: tocca la tensione sul rinforzo laterale, ma non nel tuo innesto. Un RCT su Annals of Internal Medicine mostra che quattro mesi di esercizio supervisionato dopo il crociato danno un KOOS migliore di una sola sessione educativa, con una differenza aggiustata di 4,8, intervallo da 1,4 a 8,2, che si riduce a un anno. Una revisione sistematica sulla radice meniscale conferma che né l'all-inside né il pull-out transtibiale correggono in modo costante l'estrusione: ha mosso la tensione T2b. Dal registro inglese, su quasi settecentomila protesi di ginocchio, la robotica non cambia il rischio di revisione: hazard ratio 1,03, intervallo da 0,86 a 1,26. Chiude la settimana una revisione sul MPFL: la fissazione femorale onlay appare comparabile al tunnel, non superiore. Nessun richiamo di dispositivi e nessuna ritrattazione che ti riguardi.\n\nIl lavoro del giorno è uno studio caso-controllo del Journal of ISAKOS, da Berlino: su duecentottanta pazienti con lesione cartilaginea trattati con MACI lo slope tibiale mediale è 9,73 gradi contro 8,92 nei controlli, differenza aggiustata 0,80 gradi, intervallo di confidenza da 0,32 a 1,27. L'associazione vale per rotula e troclea, non per i condili. È piccola, retrospettiva, e non dice se correggere lo slope protegga la cartilagine.\n\nAltre schede. Per il crociato posteriore, una rassegna narrativa sugli atleti d'élite riporta un rientro superiore al 90% con tutore dinamico nelle lesioni isolate acute selezionate. Una nota di tecnica propone un cordone di retinacolo mediale insieme al MPFL, senza pazienti né esiti. Nelle protesi monocompartimentali un confronto su novantasei casi non trova differenze di allineamento fra tre gruppi, con robot imageless o strumentario convenzionale. Nella protesi totale un confronto fra robotica e manuale mostra meno infiammazione al terzo giorno e tempi più lunghi, senza numeri nell'abstract. Poi il cemento da venti grammi nella monocompartimentale, che spreca meno del quaranta con fissazione comparabile, la meniscectomia con ago-artroscopio da un millimetro e nove, ventiquattro pazienti per gruppo, e l'abduzione del ginocchio nelle calciatrici ad alto rischio, che resta ridotta a sei mesi.\n\nRichiami, ritrattazioni e linee guida: nessuna novità nel perimetro. Nessuna tensione si sposta oggi.";

var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi è domenica, quindi apro con la settimana. Cinque lavori contano, dal 28 settembre al 3 ottobre."}, {"chi": "B", "t": "Quali?"}, {"chi": "A", "t": "Una coorte di trecento revisioni del crociato: con l'aumento laterale la sopravvivenza dell'innesto a cinque anni è 90,6% contro 79,9%, hazard ratio 0,46, intervallo da 0,28 a 0,74. Poi un RCT sull'esercizio supervisionato dopo il crociato: differenza aggiustata di 4,8 sul KOOS, intervallo da 1,4 a 8,2, che si riduce a un anno."}, {"chi": "B", "t": "E sul menisco e sulla robotica?"}, {"chi": "A", "t": "Una revisione conferma che né all-inside né pull-out transtibiale correggono in modo costante l'estrusione della radice. E il registro inglese, su quasi settecentomila protesi di ginocchio, non vede differenze di revisione con la robotica: hazard ratio 1,03, intervallo da 0,86 a 1,26."}, {"chi": "B", "t": "Il tuo VELYS non cambia il quadro, quindi. E oggi, il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio caso-controllo da Berlino su duecentottanta pazienti con lesione cartilaginea trattati con MACI. Lo slope tibiale mediale è 9,73 gradi contro 8,92: differenza aggiustata 0,80, intervallo da 0,32 a 1,27."}, {"chi": "B", "t": "Quindi lo slope ripido fa male alla cartilagine?"}, {"chi": "A", "t": "Non lo dice: è un'associazione, retrospettiva, e vale per rotula e troclea, non per i condili. Gli autori stessi parlano di rilevanza clinica incerta."}, {"chi": "B", "t": "E il crociato posteriore?"}, {"chi": "A", "t": "Una rassegna narrativa sugli atleti d'élite: rientro oltre il 90% con tutore dinamico nelle lesioni isolate acute selezionate, livello III. Nessuna tecnica dimostrata superiore."}, {"chi": "B", "t": "Per le protesi?"}, {"chi": "A", "t": "Nella monocompartimentale, novantasei casi: allineamento uguale con o senza robot imageless, ma sono tre gruppi piccoli, quindi nessuna prova di equivalenza. Nella totale, la robotica ha meno infiammazione al terzo giorno e tempi più lunghi, senza numeri nell'abstract."}, {"chi": "B", "t": "Nessuna tensione si sposta, mi pare."}, {"chi": "A", "t": "Esatto, e nessun richiamo né ritrattazione che ti riguardi."}];

